//! Hashing support for [`HopscotchMap`](crate::tsl::hopscotch_map::HopscotchMap).
//!
//! The C++ original instantiates `tsl::hopscotch_map<int, int>`, which defaults to
//! `std::hash<int>`.  In libstdc++ `std::hash` for every integral type is the *identity*
//! function (`static_cast<size_t>(value)`), so key `i` always lands in bucket
//! `i & (bucket_count - 1)` of a power-of-two table.
//!
//! To reproduce that bucket layout (and therefore the same neighborhood / displacement /
//! overflow behavior) this module provides [`CppStdHasher`], a `std::hash::Hasher` whose
//! integer writes are the identity, plus a deterministic FNV-1a fallback for byte slices
//! (`&str`, `String`, `Vec<u8>`, ...) so that non-integer keys still hash sensibly.
//!
//! Determinism is deliberate: unlike `std::collections::hash_map::RandomState` there is no
//! per-process seed, so a given key set always produces the same table layout, which makes
//! the hopscotch invariants unit-testable.

use std::hash::{BuildHasher, Hash, Hasher};

/// FNV-1a 64-bit offset basis.
const FNV_OFFSET_BASIS: u64 = 0xcbf2_9ce4_8422_2325;
/// FNV-1a 64-bit prime.
const FNV_PRIME: u64 = 0x0000_0100_0000_01b3;

/// A deterministic `Hasher` that mirrors libstdc++'s `std::hash`.
///
/// * The first integer written is used *verbatim* (identity hash), matching
///   `std::hash<int>::operator()` which is `static_cast<size_t>(value)`.
/// * Subsequent writes (tuples, structs, the trailing `0xff` that `Hash for str` emits) are
///   folded in with a multiply-xor mix so composite keys still spread out.
/// * Byte slices use FNV-1a, standing in for libstdc++'s `_Hash_bytes` (Murmur) helper.
#[derive(Clone, Copy, Debug)]
pub struct CppStdHasher {
    state: u64,
    /// Number of `write*` calls seen so far; `0` selects the identity fast path.
    writes: u32,
}

impl CppStdHasher {
    /// Creates a fresh hasher.
    pub const fn new() -> Self {
        CppStdHasher { state: 0, writes: 0 }
    }

    /// Folds one integer into the state.
    ///
    /// The very first integer is stored unchanged (identity hash); later ones are mixed so
    /// that `(a, b)` and `(b, a)` do not collide.
    #[inline]
    fn feed_int(&mut self, value: u64) {
        if self.writes == 0 {
            self.state = value;
        } else {
            self.state = mix64(self.state ^ value).wrapping_mul(FNV_PRIME);
        }
        self.writes = self.writes.wrapping_add(1);
    }
}

impl Default for CppStdHasher {
    fn default() -> Self {
        CppStdHasher::new()
    }
}

/// A 64-bit avalanche mix (the finalizer from SplitMix64 / MurmurHash3).
#[inline]
const fn mix64(mut x: u64) -> u64 {
    x ^= x >> 33;
    x = x.wrapping_mul(0xff51_afd7_ed55_8ccd);
    x ^= x >> 33;
    x = x.wrapping_mul(0xc4ce_b9fe_1a85_ec53);
    x ^= x >> 33;
    x
}

impl Hasher for CppStdHasher {
    #[inline]
    fn finish(&self) -> u64 {
        self.state
    }

    #[inline]
    fn write(&mut self, bytes: &[u8]) {
        let mut h = if self.writes == 0 {
            FNV_OFFSET_BASIS
        } else {
            mix64(self.state ^ FNV_OFFSET_BASIS)
        };
        for &b in bytes {
            h ^= b as u64;
            h = h.wrapping_mul(FNV_PRIME);
        }
        self.state = h;
        self.writes = self.writes.wrapping_add(1);
    }

    // ---- identity integer paths (this is what makes `std::hash<int>` behavior appear) ----

    #[inline]
    fn write_u8(&mut self, i: u8) {
        self.feed_int(i as u64)
    }
    #[inline]
    fn write_u16(&mut self, i: u16) {
        self.feed_int(i as u64)
    }
    #[inline]
    fn write_u32(&mut self, i: u32) {
        self.feed_int(i as u64)
    }
    #[inline]
    fn write_u64(&mut self, i: u64) {
        self.feed_int(i)
    }
    #[inline]
    fn write_usize(&mut self, i: usize) {
        self.feed_int(i as u64)
    }
    #[inline]
    fn write_u128(&mut self, i: u128) {
        // libstdc++ folds the two halves of a 128-bit integer together.
        self.feed_int((i as u64) ^ ((i >> 64) as u64))
    }

    // Signed writes sign-extend first, exactly like `static_cast<size_t>(negative_int)`.
    #[inline]
    fn write_i8(&mut self, i: i8) {
        self.feed_int(i as i64 as u64)
    }
    #[inline]
    fn write_i16(&mut self, i: i16) {
        self.feed_int(i as i64 as u64)
    }
    #[inline]
    fn write_i32(&mut self, i: i32) {
        self.feed_int(i as i64 as u64)
    }
    #[inline]
    fn write_i64(&mut self, i: i64) {
        self.feed_int(i as u64)
    }
    #[inline]
    fn write_isize(&mut self, i: isize) {
        self.feed_int(i as i64 as u64)
    }
    #[inline]
    fn write_i128(&mut self, i: i128) {
        self.feed_int((i as u64) ^ ((i >> 64) as u64))
    }
}

/// `BuildHasher` producing [`CppStdHasher`]; the default hasher of the map.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
pub struct CppStdHash;

impl BuildHasher for CppStdHash {
    type Hasher = CppStdHasher;

    #[inline]
    fn build_hasher(&self) -> CppStdHasher {
        CppStdHasher::new()
    }
}

/// Hashes `key` with `build_hasher`, returning the raw 64-bit digest.
#[inline]
pub fn hash_of<K, S>(build_hasher: &S, key: &K) -> u64
where
    K: Hash + ?Sized,
    S: BuildHasher,
{
    let mut hasher = build_hasher.build_hasher();
    key.hash(&mut hasher);
    hasher.finish()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn integers_hash_to_themselves() {
        for i in 0..1000i32 {
            assert_eq!(hash_of(&CppStdHash, &i), i as u64, "identity hash for {}", i);
        }
        assert_eq!(hash_of(&CppStdHash, &0u64), 0);
        assert_eq!(hash_of(&CppStdHash, &7usize), 7);
    }

    #[test]
    fn negative_integers_sign_extend_like_static_cast() {
        assert_eq!(hash_of(&CppStdHash, &-1i32), u64::MAX);
        assert_eq!(hash_of(&CppStdHash, &-5i32), (-5i64) as u64);
    }

    #[test]
    fn bool_and_char_follow_their_integer_writes() {
        assert_eq!(hash_of(&CppStdHash, &false), 0);
        assert_eq!(hash_of(&CppStdHash, &true), 1);
        assert_eq!(hash_of(&CppStdHash, &'A'), 65);
    }

    #[test]
    fn strings_are_deterministic_and_distinct() {
        let a = hash_of(&CppStdHash, "hello");
        let b = hash_of(&CppStdHash, "hello");
        let c = hash_of(&CppStdHash, "world");
        assert_eq!(a, b);
        assert_ne!(a, c);
    }

    #[test]
    fn tuples_are_order_sensitive() {
        let ab = hash_of(&CppStdHash, &(1i32, 2i32));
        let ba = hash_of(&CppStdHash, &(2i32, 1i32));
        assert_ne!(ab, ba);
    }

    #[test]
    fn mix64_is_a_bijection_on_sampled_points() {
        // Sanity: the finalizer must not collapse distinct inputs in the sampled range.
        let mut seen = std::collections::HashSet::new();
        for i in 0..2000u64 {
            assert!(seen.insert(mix64(i)));
        }
    }
}

