//! A single hopscotch bucket: a neighborhood bitmap plus an optional stored entry.
//!
//! Hopscotch hashing stores, for every *home* bucket `i`, a bitmap describing which of the
//! `NEIGHBORHOOD_SIZE` slots starting at `i` currently hold an entry whose home bucket is `i`.
//! The entry slot itself is independent of the bitmap: bucket `i`'s `entry` may belong to some
//! earlier home bucket `i - k`.
//!
//! Layout of [`Bucket::infos`] (a `u64`):
//!
//! ```text
//!  bit 63          bit 62        bits 61..0
//! +--------+-------------------+-----------------------------------+
//! | unused | overflow present  | neighborhood presence bitmap      |
//! +--------+-------------------+-----------------------------------+
//! ```
//!
//! Bit `j` of the neighborhood bitmap (`j` in `0..NEIGHBORHOOD_SIZE`) means "the slot at
//! `self_index + j` holds an entry whose home bucket is `self_index`".  The overflow bit means
//! "at least one entry whose home bucket is `self_index` lives in the overflow list".

/// Number of slots in a bucket's neighborhood.
///
/// Matches the default `NeighborhoodSize` of `tsl::hopscotch_map` (62), which leaves room in a
/// 64-bit word for the overflow flag.
pub const NEIGHBORHOOD_SIZE: usize = 62;

/// Mask covering the neighborhood presence bits.
const NEIGHBORHOOD_MASK: u64 = (1u64 << NEIGHBORHOOD_SIZE) - 1;

/// Flag bit recording that this home bucket has spilled into the overflow list.
const OVERFLOW_BIT: u64 = 1u64 << NEIGHBORHOOD_SIZE;

/// One slot of the hopscotch table.
#[derive(Clone, Debug)]
pub struct Bucket<K, V> {
    infos: u64,
    entry: Option<(K, V)>,
}

impl<K, V> Bucket<K, V> {
    /// An empty bucket with an empty neighborhood and no overflow.
    pub const fn new() -> Self {
        Bucket { infos: 0, entry: None }
    }

    /// `true` if this slot currently stores no entry.
    #[inline]
    pub fn is_empty(&self) -> bool {
        self.entry.is_none()
    }

    /// Borrows the stored entry, if any.
    #[inline]
    pub fn entry(&self) -> Option<&(K, V)> {
        self.entry.as_ref()
    }

    /// Mutably borrows the stored entry, if any.
    #[inline]
    pub fn entry_mut(&mut self) -> Option<&mut (K, V)> {
        self.entry.as_mut()
    }

    /// Consumes the bucket, yielding the stored entry.
    #[inline]
    pub fn into_entry(self) -> Option<(K, V)> {
        self.entry
    }

    /// Stores `(key, value)` in this slot.
    ///
    /// # Panics
    /// Panics if the slot is already occupied; callers must only fill empty slots.
    #[inline]
    pub fn set_entry(&mut self, key: K, value: V) {
        debug_assert!(self.entry.is_none(), "overwriting an occupied hopscotch slot");
        self.entry = Some((key, value));
    }

    /// Removes and returns the stored entry.
    #[inline]
    pub fn take_entry(&mut self) -> Option<(K, V)> {
        self.entry.take()
    }

    /// Raw neighborhood presence bitmap (overflow flag masked off).
    #[inline]
    pub fn neighborhood_bits(&self) -> u64 {
        self.infos & NEIGHBORHOOD_MASK
    }

    /// `true` if the slot `offset` positions after this bucket holds one of its entries.
    #[inline]
    pub fn is_present(&self, offset: usize) -> bool {
        debug_assert!(offset < NEIGHBORHOOD_SIZE);
        self.infos & (1u64 << offset) != 0
    }

    /// Records that the slot `offset` positions away now holds one of this bucket's entries.
    #[inline]
    pub fn set_present(&mut self, offset: usize) {
        debug_assert!(offset < NEIGHBORHOOD_SIZE);
        debug_assert!(!self.is_present(offset), "neighborhood bit set twice");
        self.infos |= 1u64 << offset;
    }

    /// Clears the presence bit for `offset`.
    #[inline]
    pub fn clear_present(&mut self, offset: usize) {
        debug_assert!(offset < NEIGHBORHOOD_SIZE);
        debug_assert!(self.is_present(offset), "clearing an unset neighborhood bit");
        self.infos &= !(1u64 << offset);
    }

    /// `true` if entries homed here may live in the overflow list.
    #[inline]
    pub fn has_overflow(&self) -> bool {
        self.infos & OVERFLOW_BIT != 0
    }

    /// Marks this home bucket as having spilled into the overflow list.
    #[inline]
    pub fn set_overflow(&mut self) {
        self.infos |= OVERFLOW_BIT;
    }

    /// Clears the overflow flag.
    #[inline]
    pub fn clear_overflow(&mut self) {
        self.infos &= !OVERFLOW_BIT;
    }

    /// Number of entries homed at this bucket that live inside the table.
    #[inline]
    pub fn neighborhood_len(&self) -> u32 {
        self.neighborhood_bits().count_ones()
    }
}

impl<K, V> Default for Bucket<K, V> {
    fn default() -> Self {
        Bucket::new()
    }
}

/// Iterator over the set offsets of a neighborhood bitmap, ascending.
pub struct NeighborhoodOffsets {
    bits: u64,
}

impl NeighborhoodOffsets {
    /// Iterates the set presence offsets of `bucket`.
    #[inline]
    pub fn new<K, V>(bucket: &Bucket<K, V>) -> Self {
        NeighborhoodOffsets { bits: bucket.neighborhood_bits() }
    }
}

impl Iterator for NeighborhoodOffsets {
    type Item = usize;

    #[inline]
    fn next(&mut self) -> Option<usize> {
        if self.bits == 0 {
            return None;
        }
        let offset = self.bits.trailing_zeros() as usize;
        self.bits &= self.bits - 1; // clear lowest set bit
        Some(offset)
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn overflow_bit_does_not_leak_into_neighborhood() {
        let mut b: Bucket<i32, i32> = Bucket::new();
        b.set_overflow();
