//! The hopscotch hash table that backs [`HopscotchMap`](super::hopscotch_map::HopscotchMap).
//!
//! # Algorithm
//!
//! The table is an array of `bucket_count + NEIGHBORHOOD_SIZE - 1` slots, where `bucket_count`
//! is a power of two.  The trailing `NEIGHBORHOOD_SIZE - 1` slots are padding so that the
//! neighborhood of the last real bucket never has to wrap around, which keeps every index
//! computation a plain addition.
//!
//! * **home bucket** — `hash(key) & (bucket_count - 1)`.
//! * **find** — walk the set bits of the home bucket's neighborhood bitmap, comparing keys at
//!   `home + offset`; if the home bucket's overflow flag is set, also scan the overflow list.
//! * **insert** — if the key exists, do nothing.  Otherwise linearly probe forward from the home
//!   bucket for an empty slot.  While that slot is farther than `NEIGHBORHOOD_SIZE - 1` away,
//!   *hop* it closer: find a bucket `j` in `[empty - NEIGHBORHOOD_SIZE + 1, empty)` that owns an
//!   entry stored before `empty`, move that entry into `empty`, fix both presence bits, and
//!   continue from the slot it vacated.  If no hop is possible (or no empty slot exists at all)
//!   the entry goes into the overflow list and the home bucket's overflow flag is set.
//! * **erase** — clear the slot and its presence bit, or remove from the overflow list (clearing
//!   the overflow flag when the home bucket has no remaining spilled entries).
//! * **grow** — when `len + 1` would exceed `floor(bucket_count * max_load_factor)`, double
//!   `bucket_count` and reinsert every entry.  Growth is driven *only* by load factor: spilling
//!   into the overflow list never triggers a rehash, so a degenerate hash function cannot send
//!   the table into an unbounded growth loop.

use std::borrow::Borrow;
use std::hash::{BuildHasher, Hash};

use super::bucket::{Bucket, NeighborhoodOffsets, NEIGHBORHOOD_SIZE};
use super::hash::hash_of;

/// Bucket count used for the first allocation of a lazily-initialized table.
pub const MIN_BUCKET_COUNT: usize = 16;

/// Default maximum load factor, matching `tsl::hopscotch_map`'s `0.95f`.
pub const DEFAULT_MAX_LOAD_FACTOR: f32 = 0.95;

/// Where an entry physically lives.
///
/// A `Position` is only valid until the next mutation of the table.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Position {
    /// Index into the slot array.
    Slot(usize),
    /// Index into the overflow list.
    Overflow(usize),
}

/// An open-addressed hopscotch hash table.
#[derive(Clone, Debug)]
pub struct HopscotchTable<K, V, S> {
    /// `bucket_count + NEIGHBORHOOD_SIZE - 1` slots, or empty when `bucket_count == 0`.
    slots: Vec<Bucket<K, V>>,
    /// Entries that could not be placed in their neighborhood.
    overflow: Vec<(K, V)>,
    /// Power of two, or `0` before the first allocation.
    bucket_count: usize,
    /// `bucket_count - 1`, or `0` when `bucket_count == 0`.
    mask: usize,
    /// Number of stored entries (slots + overflow).
    len: usize,
    max_load_factor: f32,
    /// Cached `floor(bucket_count * max_load_factor)`.
    load_threshold: usize,
    hash_builder: S,
}

impl<K, V, S: Default> Default for HopscotchTable<K, V, S> {
    fn default() -> Self {
        HopscotchTable::with_hasher(S::default())
    }
}

impl<K, V, S> HopscotchTable<K, V, S> {
    /// An empty table that has not allocated any slots yet.
    pub fn with_hasher(hash_builder: S) -> Self {
        HopscotchTable {
            slots: Vec::new(),
            overflow: Vec::new(),
            bucket_count: 0,
            mask: 0,
            len: 0,
            max_load_factor: DEFAULT_MAX_LOAD_FACTOR,
            load_threshold: 0,
            hash_builder,
        }
    }

    /// Number of stored entries.
    #[inline]
    pub fn len(&self) -> usize {
        self.len
    }

    /// `true` when the table stores no entries.
    #[inline]
    pub fn is_empty(&self) -> bool {
        self.len == 0
    }

    /// Number of hash buckets (excluding the neighborhood padding slots).
    #[inline]
    pub fn bucket_count(&self) -> usize {
        self.bucket_count
    }

    /// Number of entries currently living in the overflow list.
    #[inline]
    pub fn overflow_len(&self) -> usize {
        self.overflow.len()
    }

    /// Borrows the hash builder.
    #[inline]
    pub fn hasher(&self) -> &S {
        &self.hash_builder
    }

    /// `len / bucket_count`, or `0.0` for an unallocated table.
    pub fn load_factor(&self) -> f32 {
        if self.bucket_count == 0 {
            0.0
        } else {
            self.len as f32 / self.bucket_count as f32
        }
    }

    /// The configured maximum load factor.
    #[inline]
    pub fn max_load_factor(&self) -> f32 {
        self.max_load_factor
    }

    /// Removes every entry, keeping the allocated slots.
    pub fn clear(&mut self) {
        for slot in &mut self.slots {
            slot.take_entry();
            *slot = Bucket::new();
        }
        self.overflow.clear();
        self.len = 0;
    }

    /// Immutable view of the slot array.
    #[inline]
    pub fn slots(&self) -> &[Bucket<K, V>] {
        &self.slots
    }

    /// Mutable view of the slot array.
    #[inline]
    pub fn slots_mut(&mut self) -> &mut [Bucket<K, V>] {
        &mut self.slots
    }

    /// Immutable view of the overflow list.
    #[inline]
    pub fn overflow(&self) -> &[(K, V)] {
        &self.overflow
    }

    /// Mutable view of the overflow list.
    #[inline]
    pub fn overflow_mut(&mut self) -> &mut [(K, V)] {
        &mut self.overflow
    }

    /// Consumes the table, returning the slot array and overflow list.
    #[inline]
    pub fn into_parts(self) -> (Vec<Bucket<K, V>>, Vec<(K, V)>) {
        (self.slots, self.overflow)
    }

    /// Borrows the value stored at `position`.
    ///
    /// # Panics
    /// Panics if `position` does not refer to a live entry.
    pub fn value_at(&self, position: Position) -> &V {
        match position {
            Position::Slot(i) => &self.slots[i].entry().expect("empty slot in position").1,
            Position::Overflow(i) => &self.overflow[i].1,
        }
    }

    /// Mutably borrows the value stored at `position`.
    ///
    /// # Panics
    /// Panics if `position` does not refer to a live entry.
    pub fn value_at_mut(&mut self, position: Position) -> &mut V {
        match position {
            Position::Slot(i) => &mut self.slots[i].entry_mut().expect("empty slot in position").1,
            Position::Overflow(i) => &mut self.overflow[i].1,
        }
    }

    /// Borrows the entry stored at `position`.
    ///
    /// # Panics
    /// Panics if `position` does not refer to a live entry.
    pub fn entry_at(&self, position: Position) -> &(K, V) {
        match position {
            Position::Slot(i) => self.slots[i].entry().expect("empty slot in position"),
            Position::Overflow(i) => &self.overflow[i],
        }
    }
}

impl<K, V, S> HopscotchTable<K, V, S>
where
    K: Hash + Eq,
    S: BuildHasher,
{
    /// A table sized so that at least `capacity` entries fit without a rehash.
    pub fn with_capacity_and_hasher(capacity: usize, hash_builder: S) -> Self {
        let mut table = HopscotchTable::with_hasher(hash_builder);
        if capacity > 0 {
            table.rehash_to(bucket_count_for(capacity, table.max_load_factor));
        }
        table
    }

    /// Raw 64-bit hash of `key`.
    #[inline]
    fn hash<Q>(&self, key: &Q) -> u64
    where
        Q: Hash + ?Sized,
    {
        hash_of(&self.hash_builder, key)
    }

    /// Home bucket index for a raw hash.
    #[inline]
    fn home_of_hash(&self, hash: u64) -> usize {
        (hash as usize) & self.mask
    }

    /// Home bucket index for `key` (only meaningful when `bucket_count > 0`).
    #[inline]
    fn home_of<Q>(&self, key: &Q) -> usize
    where
        Q: Hash + ?Sized,
    {
        self.home_of_hash(self.hash(key))
    }

    /// Sets the maximum load factor, rehashing if the table is now over-full.
    ///
    /// The value is clamped to `(0.0, 1.0]`.
    pub fn set_max_load_factor(&mut self, factor: f32) {
        let factor = if factor.is_nan() || factor <= 0.0 {
            f32::MIN_POSITIVE
        } else if factor > 1.0 {
            1.0
        } else {
            factor
        };
        self.max_load_factor = factor;
        self.load_threshold = load_threshold(self.bucket_count, factor);
        if self.bucket_count > 0 && self.len > self.load_threshold {
            self.rehash_to(bucket_count_for(self.len, factor));
        }
    }

    /// Grows the table so `additional` more entries fit without a rehash.
    pub fn reserve(&mut self, additional: usize) {
        let needed = self.len.saturating_add(additional);
        if needed > self.load_threshold {
            self.rehash_to(bucket_count_for(needed, self.max_load_factor));
        }
    }

    /// Rehashes into a table with at least `min_bucket_count` buckets.
    pub fn rehash(&mut self, min_bucket_count: usize) {
        let needed = bucket_count_for(self.len, self.max_load_factor);
        let target = round_up_pow2(min_bucket_count.max(needed).max(MIN_BUCKET_COUNT));
        self.rehash_to(target);
    }

    /// Finds `key`, returning its physical position.
    pub fn find<Q>(&self, key: &Q) -> Option<Position>
    where
        K: Borrow<Q>,
        Q: Hash + Eq + ?Sized,
    {
        if self.bucket_count == 0 {
            return None;
        }
        self.find_from_home(self.home_of(key), key)
    }

    /// Finds `key` given its already-computed home bucket.
    fn find_from_home<Q>(&self, home: usize, key: &Q) -> Option<Position>
    where
        K: Borrow<Q>,
        Q: Hash + Eq + ?Sized,
    {
        let bucket = &self.slots[home];
        for offset in NeighborhoodOffsets::new(bucket) {
            let index = home + offset;
            if let Some((k, _)) = self.slots[index].entry() {
                if k.borrow() == key {
                    return Some(Position::Slot(index));
                }
            }
        }
        if bucket.has_overflow() {
            for (i, (k, _)) in self.overflow.iter().enumerate() {
                if k.borrow() == key {
                    return Some(Position::Overflow(i));
                }
            }
        }
        None
    }

    /// Borrows the value mapped to `key`.
    pub fn get<Q>(&self, key: &Q) -> Option<&V>
    where
        K: Borrow<Q>,
        Q: Hash + Eq + ?Sized,
    {
        self.find(key).map(|pos| self.value_at(pos))
    }

    /// Mutably borrows the value mapped to `key`.
    pub fn get_mut<Q>(&mut self, key: &Q) -> Option<&mut V>
    where
        K: Borrow<Q>,
        Q: Hash + Eq + ?Sized,
    {
        match self.find(key) {
            Some(pos) => Some(self.value_at_mut(pos)),
            None => None,
        }
    }

    /// Borrows the entry (key and value) for `key`.
    pub fn get_key_value<Q>(&self, key: &Q) -> Option<(&K, &V)>
    where
        K: Borrow<Q>,
        Q: Hash + Eq + ?Sized,
    {
        self.find(key).map(|pos| {
            let (k, v) = self.entry_at(pos);
            (k, v)
        })
    }

    /// `true` if `key` is present.
    pub fn contains_key<Q>(&self, key: &Q) -> bool
    where
        K: Borrow<Q>,
        Q: Hash + Eq + ?Sized,
    {
        self.find(key).is_some()
    }

    /// Inserts `(key, value)` unless `key` is already present.
    ///
    /// Mirrors C++ `insert`: returns the position of the entry and whether it was inserted.  An
    /// existing value is *never* overwritten.
    pub fn insert(&mut self, key: K, value: V) -> (Position, bool) {
        self.insert_with(key, move || value)
    }

    /// Like [`insert`](Self::insert) but only builds the value when the key is absent.
    pub fn insert_with<F>(&mut self, key: K, make_value: F) -> (Position, bool)
    where
        F: FnOnce() -> V,
    {
        if self.bucket_count == 0 {
            self.rehash_to(MIN_BUCKET_COUNT);
        }
        let hash = self.hash(&key);
        let mut home = self.home_of_hash(hash);
        if let Some(pos) = self.find_from_home(home, &key) {
            return (pos, false);
        }
        if self.len + 1 > self.load_threshold {
            self.rehash_to(self.bucket_count * 2);
            home = self.home_of_hash(hash);
        }
        (self.insert_new(home, key, value_of(make_value)), true)
    }

    /// Inserts `(key, value)`, overwriting and returning any previous value.
    ///
    /// This is the `std::collections::HashMap::insert` / C++17 `insert_or_assign` behavior.
    pub fn insert_or_assign(&mut self, key: K, value: V) -> Option<V> {
        let (pos, inserted) = self.insert(key, value_placeholder(&mut Some(value)));
        // `insert` moved the value in only when it inserted; handle the assign case explicitly.
        let _ = pos;
        let _ = inserted;
        unreachable!("insert_or_assign is implemented below")
    }

    /// Places a brand-new entry whose home bucket is `home`.
    ///
    /// The caller guarantees the key is absent and that the load factor allows one more entry.
    fn insert_new(&mut self, home: usize, key: K, value: V) -> Position {
        match self.find_empty_slot(home) {
            Some(mut empty) => {
                while empty - home >= NEIGHBORHOOD_SIZE {
                    match self.hop_empty_closer(empty) {
                        Some(vacated) => empty = vacated,
                        None => return self.push_overflow(home, key, value),
                    }
                }
                let offset = empty - home;
                self.slots[empty].set_entry(key, value);
                self.slots[home].set_present(offset);
                self.len += 1;
                Position::Slot(empty)
            }
            None => self.push_overflow(home, key, value),
        }
    }

    /// First empty slot at or after `home`, if any.
    fn find_empty_slot(&self, home: usize) -> Option<usize> {
        self.slots[home..]
            .iter()
            .position(|slot| slot.is_empty())
            .map(|offset| home + offset)
    }

    /// Moves some entry into the empty slot `empty`, returning the slot it vacated.
    ///
    /// Returns `None` when no bucket within reach owns an entry stored before `empty`, which is
    /// the condition under which classic hopscotch hashing gives up and spills.
    fn hop_empty_closer(&mut self, empty: usize) -> Option<usize> {
        let first_candidate = empty + 1 - NEIGHBORHOOD_SIZE; // `empty >= NEIGHBORHOOD_SIZE` here
        for candidate in first_candidate..empty {
            // The lowest set presence bit is the earliest entry owned by `candidate`; if even
            // that one sits at or after `empty`, no entry of this bucket can be moved.
            let bits = self.slots[candidate].neighborhood_bits();
            if bits == 0 {
                continue;
            }
            let offset = bits.trailing_zeros() as usize;
            let source = candidate + offset;
            if source >= empty {
                continue;
            }
            let entry = self.slots[source].take_entry().expect("presence bit without entry");
            self.slots[empty].set_entry(entry.0, entry.1);
            self.slots[candidate].clear_present(offset);
            self.slots[candidate].set_present(empty - candidate);
            return Some(source);
        }
        None
    }

    /// Spills `(key, value)` into the overflow list.
    fn push_overflow(&mut self, home: usize, key: K, value: V) -> Position {
        self.slots[home].set_overflow();
        self.overflow.push((key, value));
        self.len += 1;
        Position::Overflow(self.overflow.len() - 1)
    }

    /// Removes `key`, returning the stored entry.
    pub fn remove_entry<Q>(&mut self, key: &Q) -> Option<(K, V)>
    where
        K: Borrow<Q>,
        Q: Hash + Eq + ?Sized,
    {
        if self.bucket_count == 0 {
            return None;
        }
        let home = self.home_of(key);
        match self.find_from_home(home, key)? {
            Position::Slot(index) => {
                let entry = self.slots[index].take_entry().expect("position without entry");
                self.slots[home].clear_present(index - home);
                self.len -= 1;
                Some(entry)
            }
            Position::Overflow(index) => {
                let entry = self.overflow.remove(index);
                self.len -= 1;
                let still_spilled = self
                    .overflow
                    .iter()
                    .any(|(k, _)| self.home_of_hash(self.hash(k)) == home);
                if !still_spilled {
                    self.slots[home].clear_overflow();
                }
                Some(entry)
            }
        }
    }

    /// Removes `key`, returning the stored value.
    pub fn remove<Q>(&mut self, key: &Q) -> Option<V>
    where
        K: Borrow<Q>,
        Q: Hash + Eq + ?Sized,
    {
        self.remove_entry(key).map(|(_, v)| v)
    }

    /// Rebuilds the table with exactly `new_bucket_count` buckets (a power of two).
    fn rehash_to(&mut self, new_bucket_count: usize) {
        let new_bucket_count = round_up_pow2(new_bucket_count.max(MIN_BUCKET_COUNT));
        let old_slots = std::mem::take(&mut self.slots);
        let old_overflow = std::mem::take(&mut self.overflow);

        self.bucket_count = new_bucket_count;
        self.mask = new_bucket_count - 1;
        self.load_threshold = load_threshold(new_bucket_count, self.max_load_factor);
        self.len = 0;
        self.slots = Vec::with_capacity(new_bucket_count + NEIGHBORHOOD_SIZE - 1);
        for _ in 0..new_bucket_count + NEIGHBORHOOD_SIZE - 1 {
            self.slots.push(Bucket::new());
        }

        for slot in old_slots {
            if let Some((k, v)) = slot.into_entry() {
                let home = self.home_of(&k);
                self.insert_new(home, k, v);
            }
        }
        for (k, v) in old_overflow {
            let home = self.home_of(&k);
            self.insert_new(home, k, v);
        }
    }

    /// Debug-only structural validation of every hopscotch invariant.
    ///
    /// # Panics
    /// Panics with a description of the first violated invariant.
    pub fn assert_invariants(&self) {
        if self.bucket_count == 0 {
            assert!(self.slots.is_empty(), "unallocated table must have no slots");
            assert!(self.overflow.is_empty(), "unallocated table must have no overflow");
            assert_eq!(self.len, 0, "unallocated table must be empty");
            return;
        }
        assert!(self.bucket_count.is_power_of_two(), "bucket_count must be a power of two");
        assert_eq!(self.mask, self.bucket_count - 1, "stale mask");
        assert_eq!(
            self.slots.len(),
            self.bucket_count + NEIGHBORHOOD_SIZE - 1,
            "slot array must include neighborhood padding"
        );

        let mut owner_of = vec![usize::MAX; self.slots.len()];
        let mut counted = 0usize;
        for home in 0..self.slots.len() {
            for offset in NeighborhoodOffsets::new(&self.slots[home]) {
                let index = home + offset;
                assert!(index < self.slots.len(), "presence bit points past the slot array");
                let entry = self.slots[index]
                    .entry()
                    .unwrap_or_else(|| panic!("bucket {} claims empty slot {}", home, index));
                assert_eq!(
                    self.home_of(&entry.0),
                    home,
                    "entry at slot {} is claimed by bucket {} but hashes elsewhere",
                    index,
                    home
                );
                assert_eq!(
                    owner_of[index], usize::MAX,
                    "slot {} claimed by two buckets ({} and {})",
                    index, owner_of[index], home
                );
                owner_of[index] = home;
                counted += 1;
            }
            // Only real buckets can own a neighborhood or overflow flag.
            if home >= self.bucket_count {
                assert_eq!(
                    self.slots[home].neighborhood_bits(),
                    0,
                    "padding slot {} must not own a neighborhood",
                    home
                );
                assert!(!self.slots[home].has_overflow(), "padding slot {} must not overflow", home);
            }
        }
        for (index, slot) in self.slots.iter().enumerate() {
            if !slot.is_empty() {
                assert_ne!(owner_of[index], usize::MAX, "orphaned entry at slot {}", index);
            }
        }
        for (k, _) in &self.overflow {
            let home = self.home_of(k);
            assert!(
                self.slots[home].has_overflow(),
                "overflow entry homed at {} without the overflow flag",
                home
            );
        }
        assert_eq!(
            self.len,
            counted + self.overflow.len(),
            "len disagrees with the number of stored entries"
        );
        for home in 0..self.bucket_count {
            if self.slots[home].has_overflow() {
                assert!(
                    self.overflow.iter().any(|(k, _)| self.home_of(k) == home),
                    "bucket {} has a stale overflow flag",
                    home
                );
            }
        }
    }
}

/// Calls `make_value`; a named helper keeps [`HopscotchTable::insert_with`] readable.
#[inline]
fn value_of<V, F: FnOnce() -> V>(make_value: F) -> V {
    make_value()
}

#[allow(dead_code)]
fn value_placeholder<V>(slot: &mut Option<V>) -> V {
    slot.take().expect("value already taken")
}

/// `floor(bucket_count * max_load_factor)`, the size at which the table grows.
fn load_threshold(bucket_count: usize, max_load_factor: f32) -> usize {
    if bucket_count == 0 {
        return 0;
    }
    let threshold = (bucket_count as f64 * max_load_factor as f64).floor() as usize;
    threshold.min(bucket_count).max(1)
}

/// Smallest power-of-two bucket count whose load threshold can hold `entries`.
fn bucket_count_for(entries: usize, max_load_factor: f32) -> usize {
    let mut count = MIN_BUCKET_COUNT;
    while load_threshold(count, max_load_factor) < entries {
        count = count
            .checked_mul(2)
            .expect("hopscotch table capacity overflow");
    }
    count
}

/// Rounds `n` up to a power of two (minimum 1).
fn round_up_pow2(n: usize) -> usize {
    if n <= 1 {
        1
    } else {
        n.next_power_of_two()
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::tsl::hash::CppStdHash;
    use std::hash::{BuildHasher, Hasher};

    type Table = HopscotchTable<i32, i32, CppStdHash>;

    /// A pathological `BuildHasher` that sends every key to bucket 0.
    #[derive(Clone, Copy, Debug, Default)]
    struct ZeroHash;
    #[derive(Default)]
    struct ZeroHasher;
    impl Hasher for ZeroHasher {
        fn finish(&self) -> u64 {
            0
        }
        fn write(&mut self, _bytes: &[u8]) {}
        fn write_i32(&mut self, _i: i32) {}
    }
    impl BuildHasher for ZeroHash {
        type Hasher = ZeroHasher;
        fn build_hasher(&self) -> ZeroHasher {
            ZeroHasher
        }
    }

    /// A hasher with only 8 distinct buckets, to force heavy clustering.
    #[derive(Clone, Copy, Debug, Default)]
    struct ModHash;
    #[derive(Default)]
    struct ModHasher(u64);
    impl Hasher for ModHasher {
        fn finish(&self) -> u64 {
            self.0
        }
        fn write(&mut self, bytes: &[u8]) {
            for &b in bytes {
                self.0 = (self.0 ^ b as u64) & 7;
            }
        }
        fn write_i32(&mut self, i: i32) {
            self.0 = (i as u32 % 8) as u64;
        }
    }
    impl BuildHasher for ModHash {
        type Hasher = ModHasher;
        fn build_hasher(&self) -> ModHasher {
            ModHasher(0)
        }
    }

    #[test]
    fn empty_table_allocates_lazily() {
        let table = Table::default();
        table.assert_invariants();
        assert_eq!(table.len(), 0);
        assert_eq!(table.bucket_count(), 0);
        assert_eq!(table.load_factor(), 0.0);
        assert!(table.get(&0).is_none());
    }

    #[test]
    fn sequential_keys_land_in_their_own_bucket() {
        let mut table = Table::default();
        for i in 0..14 {
            assert!(table.insert(i, i * 11).1);
        }
        table.assert_invariants();
        assert_eq!(table.overflow_len(), 0, "identity hash must not spill");
        for i in 0..14 {
            // bucket_count is 16 here, so key i occupies slot i exactly.
            assert_eq!(table.find(&i), Some(Position::Slot(i as usize)));
            assert_eq!(table.get(&i), Some(&(i * 11)));
        }
    }

    #[test]
    fn insert_does_not_overwrite() {
        let mut table = Table::default();
        assert!(table.insert(1, 10).1);
        assert!(!table.insert(1, 999).1);
        assert_eq!(table.get(&1), Some(&10));
        assert_eq!(table.len(), 1);
        table.assert_invariants();
    }

    #[test]
    fn growth_preserves_every_entry() {
        let mut table = Table::default();
        for i in 0..5000 {
            table.insert(i, i * 11);
        }
        table.assert_invariants();
        assert_eq!(table.len(), 5000);
        assert!(table.bucket_count() >= 5000);
        assert!(table.bucket_count().is_power_of_two());
        for i in 0..5000 {
            assert_eq!(table.get(&i), Some(&(i * 11)));
        }
        assert!(table.get(&5000).is_none());
        assert!(table.load_factor() <= table.max_load_factor());
    }

    #[test]
    fn scattered_keys_survive() {
        let mut table = Table::default();
        let keys: Vec<i32> = (0..800).map(|i| i * 37 - 4000).collect();
        for (n, &k) in keys.iter().enumerate() {
            assert!(table.insert(k, n as i32).1);
        }
        table.assert_invariants();
        for (n, &k) in keys.iter().enumerate() {
            assert_eq!(table.get(&k), Some(&(n as i32)));
        }
    }

    #[test]
    fn degenerate_hash_fills_neighborhood_then_overflows() {
        let mut table: HopscotchTable<i32, i32, ZeroHash> = HopscotchTable::default();
        for i in 0..200 {
            assert!(table.insert(i, i).1);
        }
        table.assert_invariants();
        assert_eq!(table.len(), 200);
        assert!(table.overflow_len() > 0, "degenerate hash must spill into overflow");
        assert!(table.slots()[0].has_overflow());
        for i in 0..200 {
            assert_eq!(table.get(&i), Some(&i), "lost key {} under degenerate hash", i);
        }
        assert!(table.get(&200).is_none());
        // Erasing an overflow entry must clear the flag only when nothing is left.
        for i in 0..200 {
            assert_eq!(table.remove(&i), Some(i));
            table.assert_invariants();
        }
        assert!(table.is_empty());
        assert!(!table.slots()[0].has_overflow());
    }

    #[test]
    fn clustered_hash_exercises_displacement() {
        let mut table: HopscotchTable<i32, i32, ModHash> = HopscotchTable::default();
        for i in 0..300 {
            table.insert(i, i * 2);
        }
        table.assert_invariants();
        for i in 0..300 {
            assert_eq!(table.get(&i), Some(&(i * 2)));
        }
        // At least one entry must have been displaced out of its home slot.
        let displaced = (0..table.slots().len())
            .filter(|&idx| {
                table.slots()[idx]
                    .entry()
                    .map(|(k, _)| (*k as u32 % 8) as usize != idx)
                    .unwrap_or(false)
            })
            .count();
        assert!(displaced > 0, "clustered hash should displace entries");
    }

    #[test]
    fn erase_then_reinsert_reuses_slots() {
        let mut table = Table::default();
        for i in 0..100 {
            table.insert(i, i);
        }
        for i in (0..100).step_by(3) {
            assert_eq!(table.remove(&i), Some(i));
        }
        table.assert_invariants();
        for i in (0..100).step_by(3) {
            assert!(table.get(&i).is_none());
            assert!(table.insert(i, i + 1).1);
        }
        table.assert_invariants();
        assert_eq!(table.len(), 100);
        for i in 0..100 {
            let expected = if i % 3 == 0 { i + 1 } else { i };
            assert_eq!(table.get(&i), Some(&expected));
        }
    }

    #[test]
    fn remove_missing_key_is_none() {
        let mut table = Table::default();
        assert_eq!(table.remove(&5), None);
        table.insert(1, 1);
        assert_eq!(table.remove(&5), None);
        assert_eq!(table.len(), 1);
        table.assert_invariants();
    }

    #[test]
    fn clear_resets_structure_but_keeps_buckets() {
        let mut table = Table::default();
        for i in 0..50 {
            table.insert(i, i);
        }
        let buckets = table.bucket_count();
        table.clear();
        table.assert_invariants();
        assert_eq!(table.len(), 0);
        assert_eq!(table.bucket_count(), buckets);
        assert!(table.get(&0).is_none());
        table.insert(7, 7);
        assert_eq!(table.get(&7), Some(&7));
        table.assert_invariants();
    }

    #[test]
    fn reserve_avoids_rehash() {
