#[inline]
fn value_of<V, F: FnOnce() -> V>(make_value: F) -> V {
    make_value()
}

#[allow(dead_code)]
fn value_placeholder<V>(slot: &mut Option<V>) -> V {
    slot.take().expect("value already taken")
}

/// `floor(bucket_count * max_load_factor)`, the size at which the table grows.
fn load_threshold(bucket_count: usize, max_load_factor: f32) -> usize {
    if bucket_count == 0 {
        return 0;
    }
    let threshold = (bucket_count as f64 * max_load_factor as f64).floor() as usize;
    threshold.min(bucket_count).max(1)
}

