//! Iterators over a [`HopscotchMap`](super::hopscotch_map::HopscotchMap).
//!
//! Every iterator walks the slot array first and then the overflow list, so iteration order is an
//! implementation detail of the current table layout — exactly like `tsl::hopscotch_map`'s
//! iterators, and exactly why map equality must be order independent.

use std::iter::FusedIterator;

use super::bucket::Bucket;

/// Shared-reference iterator yielding `(&K, &V)`.
pub struct Iter<'a, K, V> {
    slots: std::slice::Iter<'a, Bucket<K, V>>,
    overflow: std::slice::Iter<'a, (K, V)>,
    remaining: usize,
}

impl<'a, K, V> Iter<'a, K, V> {
    /// Builds an iterator over `slots` followed by `overflow`, yielding `len` items.
    pub(crate) fn new(slots: &'a [Bucket<K, V>], overflow: &'a [(K, V)], len: usize) -> Self {
        Iter { slots: slots.iter(), overflow: overflow.iter(), remaining: len }
    }
}

impl<'a, K, V> Iterator for Iter<'a, K, V> {
    type Item = (&'a K, &'a V);

    fn next(&mut self) -> Option<Self::Item> {
        for slot in self.slots.by_ref() {
            if let Some((k, v)) = slot.entry() {
                self.remaining -= 1;
                return Some((k, v));
            }
        }
        let (k, v) = self.overflow.next()?;
        self.remaining -= 1;
        Some((k, v))
    }

    fn size_hint(&self) -> (usize, Option<usize>) {
        (self.remaining, Some(self.remaining))
    }
}

impl<'a, K, V> ExactSizeIterator for Iter<'a, K, V> {
    fn len(&self) -> usize {
        self.remaining
    }
}

impl<'a, K, V> FusedIterator for Iter<'a, K, V> {}

impl<'a, K, V> Clone for Iter<'a, K, V> {
    fn clone(&self) -> Self {
        Iter {
            slots: self.slots.clone(),
            overflow: self.overflow.clone(),
            remaining: self.remaining,
        }
    }
}

impl<'a, K: std::fmt::Debug, V: std::fmt::Debug> std::fmt::Debug for Iter<'a, K, V> {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.debug_list().entries(self.clone()).finish()
    }
}

/// Mutable-reference iterator yielding `(&K, &mut V)`.
pub struct IterMut<'a, K, V> {
    slots: std::slice::IterMut<'a, Bucket<K, V>>,
    overflow: std::slice::IterMut<'a, (K, V)>,
    remaining: usize,
}

impl<'a, K, V> IterMut<'a, K, V> {
    /// Builds a mutable iterator over `slots` followed by `overflow`, yielding `len` items.
    pub(crate) fn new(
        slots: &'a mut [Bucket<K, V>],
        overflow: &'a mut [(K, V)],
        len: usize,
    ) -> Self {
        IterMut { slots: slots.iter_mut(), overflow: overflow.iter_mut(), remaining: len }
    }
}

impl<'a, K, V> Iterator for IterMut<'a, K, V> {
    type Item = (&'a K, &'a mut V);

    fn next(&mut self) -> Option<Self::Item> {
        for slot in self.slots.by_ref() {
            if let Some((k, v)) = slot.entry_mut() {
                self.remaining -= 1;
                return Some((&*k, v));
            }
        }
        let (k, v) = self.overflow.next()?;
        self.remaining -= 1;
        Some((&*k, v))
    }

    fn size_hint(&self) -> (usize, Option<usize>) {
        (self.remaining, Some(self.remaining))
    }
}

impl<'a, K, V> ExactSizeIterator for IterMut<'a, K, V> {
    fn len(&self) -> usize {
        self.remaining
    }
}

impl<'a, K, V> FusedIterator for IterMut<'a, K, V> {}

/// Owning iterator yielding `(K, V)`.
pub struct IntoIter<K, V> {
    slots: std::vec::IntoIter<Bucket<K, V>>,
    overflow: std::vec::IntoIter<(K, V)>,
    remaining: usize,
}

impl<K, V> IntoIter<K, V> {
    /// Builds an owning iterator over `slots` followed by `overflow`, yielding `len` items.
    pub(crate) fn new(slots: Vec<Bucket<K, V>>, overflow: Vec<(K, V)>, len: usize) -> Self {
        IntoIter { slots: slots.into_iter(), overflow: overflow.into_iter(), remaining: len }
    }
}

impl<K, V> Iterator for IntoIter<K, V> {
    type Item = (K, V);

    fn next(&mut self) -> Option<Self::Item> {
        for slot in self.slots.by_ref() {
            if let Some(entry) = slot.into_entry() {
                self.remaining -= 1;
                return Some(entry);
            }
        }
        let entry = self.overflow.next()?;
        self.remaining -= 1;
        Some(entry)
    }

    fn size_hint(&self) -> (usize, Option<usize>) {
        (self.remaining, Some(self.remaining))
    }
}

impl<K, V> ExactSizeIterator for IntoIter<K, V> {
    fn len(&self) -> usize {
        self.remaining
    }
}

impl<K, V> FusedIterator for IntoIter<K, V> {}

/// Iterator over keys.
pub struct Keys<'a, K, V> {
    inner: Iter<'a, K, V>,
}

impl<'a, K, V> Keys<'a, K, V> {
    pub(crate) fn new(inner: Iter<'a, K, V>) -> Self {
        Keys { inner }
    }
}

impl<'a, K, V> Iterator for Keys<'a, K, V> {
    type Item = &'a K;

    fn next(&mut self) -> Option<&'a K> {
