//! A Rust port of `tsl::hopscotch_map`.
//!
//! # Relationship to the C++ original
//!
//! | C++ (`tsl::hopscotch_map`)            | Rust ([`HopscotchMap`])                                |
//! |---------------------------------------|--------------------------------------------------------|
//! | `map.insert({k, v})`                  | [`insert_pair`](HopscotchMap::insert_pair) / [`insert`](HopscotchMap::insert) — keeps the existing value |
//! | `map[k] = v`                          | `map[&k] = v` (via [`IndexMut`]) or [`get_or_insert_default`](HopscotchMap::get_or_insert_default) |
//! | `map.at(k)`                           | [`at`](HopscotchMap::at) (panics instead of throwing)  |
//! | `map.find(k) != map.end()`            | [`contains_key`](HopscotchMap::contains_key)           |
//! | `map.count(k)`                        | [`count`](HopscotchMap::count)                         |
//! | `map.erase(k)`                        | [`remove`](HopscotchMap::remove)                       |
//! | `map1 == map2`                        | `map1 == map2` (order independent)                     |
//!
//! Note the one deliberate divergence from `std::collections::HashMap`:
//! [`insert`](HopscotchMap::insert) does **not** overwrite an existing value, because C++
//! `insert` does not either.  Use [`insert_or_assign`](HopscotchMap::insert_or_assign) for the
//! `HashMap`-style "replace and return the old value" behavior.

use std::borrow::Borrow;
use std::fmt;
use std::hash::{BuildHasher, Hash};
use std::ops::{Index, IndexMut};

use super::hash::CppStdHash;
use super::iter::{IntoIter, Iter, IterMut, Keys, Values, ValuesMut};
use super::table::{HopscotchTable, Position};

/// A hash map implemented with hopscotch hashing.
///
/// See the [module documentation](self) for the mapping between this API and the C++ original.
#[derive(Clone)]
pub struct HopscotchMap<K, V, S = CppStdHash> {
    table: HopscotchTable<K, V, S>,
}

impl<K, V> HopscotchMap<K, V, CppStdHash> {
    /// Creates an empty map that has not allocated any buckets yet.
    ///
    /// Mirrors the default-constructed `tsl::hopscotch_map`, whose `bucket_count()` is `0`.
    pub fn new() -> Self {
        HopscotchMap { table: HopscotchTable::with_hasher(CppStdHash) }
    }

    /// Creates an empty map sized to hold at least `capacity` entries without rehashing.
    pub fn with_capacity(capacity: usize) -> Self
    where
        K: Hash + Eq,
    {
        HopscotchMap { table: HopscotchTable::with_capacity_and_hasher(capacity, CppStdHash) }
    }
}

impl<K, V, S> HopscotchMap<K, V, S> {
    /// Creates an empty map using `hash_builder`.
    pub fn with_hasher(hash_builder: S) -> Self {
        HopscotchMap { table: HopscotchTable::with_hasher(hash_builder) }
    }

    /// Number of entries. Mirrors C++ `size()`.
    #[inline]
    pub fn len(&self) -> usize {
        self.table.len()
    }

    /// `true` when the map holds no entries. Mirrors C++ `empty()`.
    #[inline]
    pub fn is_empty(&self) -> bool {
        self.table.is_empty()
    }

    /// Number of hash buckets. Mirrors C++ `bucket_count()`.
    #[inline]
    pub fn bucket_count(&self) -> usize {
        self.table.bucket_count()
    }

    /// Number of entries currently held in the overflow list.
    #[inline]
    pub fn overflow_len(&self) -> usize {
        self.table.overflow_len()
    }

    /// `len() / bucket_count()`. Mirrors C++ `load_factor()`.
    #[inline]
    pub fn load_factor(&self) -> f32 {
        self.table.load_factor()
    }

    /// The load factor above which the map grows. Mirrors C++ `max_load_factor()`.
    #[inline]
    pub fn max_load_factor(&self) -> f32 {
        self.table.max_load_factor()
    }

    /// Borrows the hash builder. Mirrors C++ `hash_function()`.
    #[inline]
    pub fn hasher(&self) -> &S {
        self.table.hasher()
    }

    /// Removes all entries, keeping the allocated buckets. Mirrors C++ `clear()`.
    #[inline]
    pub fn clear(&mut self) {
        self.table.clear();
    }

    /// Exchanges the contents of two maps. Mirrors C++ `swap()`.
    #[inline]
    pub fn swap(&mut self, other: &mut Self) {
        std::mem::swap(self, other);
    }

    /// Iterator over `(&K, &V)` in unspecified order. Mirrors C++ `begin()`/`end()`.
    #[inline]
    pub fn iter(&self) -> Iter<'_, K, V> {
        Iter::new(self.table.slots(), self.table.overflow(), self.table.len())
    }

    /// Iterator over `(&K, &mut V)` in unspecified order.
    #[inline]
    pub fn iter_mut(&mut self) -> IterMut<'_, K, V> {
        let len = self.table.len();
        // Split the borrow so both halves of the table can be walked mutably.
        let HopscotchTable { .. } = self.table;
        let (slots, overflow) = self.table.parts_mut();
        IterMut::new(slots, overflow, len)
    }

    /// Iterator over keys.
    #[inline]
    pub fn keys(&self) -> Keys<'_, K, V> {
        Keys::new(self.iter())
    }

    /// Iterator over values.
    #[inline]
    pub fn values(&self) -> Values<'_, K, V> {
        Values::new(self.iter())
    }

    /// Iterator over mutable values.
    #[inline]
    pub fn values_mut(&mut self) -> ValuesMut<'_, K, V> {
        ValuesMut::new(self.iter_mut())
    }

    /// Panics unless every hopscotch invariant holds; used by the test suite.
    #[cfg(test)]
    pub fn assert_invariants(&self)
    where
        K: Hash + Eq,
        S: BuildHasher,
    {
        self.table.assert_invariants();
    }
}

impl<K, V, S> HopscotchMap<K, V, S>
where
    K: Hash + Eq,
    S: BuildHasher,
{
    /// Creates a map with room for `capacity` entries, using `hash_builder`.
    pub fn with_capacity_and_hasher(capacity: usize, hash_builder: S) -> Self {
        HopscotchMap { table: HopscotchTable::with_capacity_and_hasher(capacity, hash_builder) }
    }

    /// Grows the map so `additional` more entries fit without rehashing. Mirrors C++ `reserve()`.
    #[inline]
    pub fn reserve(&mut self, additional: usize) {
        self.table.reserve(additional);
    }

    /// Rehashes into a table with at least `min_bucket_count` buckets. Mirrors C++ `rehash()`.
    #[inline]
    pub fn rehash(&mut self, min_bucket_count: usize) {
        self.table.rehash(min_bucket_count);
    }

    /// Sets the maximum load factor. Mirrors C++ `max_load_factor(float)`.
    #[inline]
    pub fn set_max_load_factor(&mut self, factor: f32) {
        self.table.set_max_load_factor(factor);
    }

    /// Inserts `(key, value)` **without** overwriting an existing entry.
    ///
    /// Returns `true` when the entry was inserted — the `bool` of C++'s
    /// `std::pair<iterator, bool> insert(const value_type&)`.
    #[inline]
    pub fn insert(&mut self, key: K, value: V) -> bool {
        self.table.insert(key, value).1
    }

    /// Exactly C++ `map.insert({key, value})`.
    #[inline]
    pub fn insert_pair(&mut self, entry: (K, V)) -> bool {
        self.insert(entry.0, entry.1)
    }

    /// Inserts, overwriting any existing value and returning it.
    ///
    /// This is what `std::collections::HashMap::insert` does, and what C++17's
    /// `insert_or_assign` does.
    #[inline]
    pub fn insert_or_assign(&mut self, key: K, value: V) -> Option<V> {
        self.table.insert_or_assign(key, value)
    }

    /// Borrows the value for `key`. Mirrors `map.find(key)`.
    #[inline]
    pub fn get<Q>(&self, key: &Q) -> Option<&V>
    where
        K: Borrow<Q>,
        Q: Hash + Eq + ?Sized,
    {
        self.table.get(key)
    }

    /// Mutably borrows the value for `key`.
    #[inline]
    pub fn get_mut<Q>(&mut self, key: &Q) -> Option<&mut V>
    where
        K: Borrow<Q>,
        Q: Hash + Eq + ?Sized,
    {
        self.table.get_mut(key)
    }

    /// Borrows the stored key together with its value.
    #[inline]
    pub fn get_key_value<Q>(&self, key: &Q) -> Option<(&K, &V)>
    where
        K: Borrow<Q>,
        Q: Hash + Eq + ?Sized,
    {
        self.table.get_key_value(key)
    }

    /// `true` when `key` is present. Mirrors C++20 `contains()`.
    #[inline]
    pub fn contains_key<Q>(&self, key: &Q) -> bool
    where
        K: Borrow<Q>,
        Q: Hash + Eq + ?Sized,
    {
        self.table.contains_key(key)
    }

    /// `1` when `key` is present, else `0`. Mirrors C++ `count()`.
    #[inline]
    pub fn count<Q>(&self, key: &Q) -> usize
    where
        K: Borrow<Q>,
        Q: Hash + Eq + ?Sized,
    {
        usize::from(self.contains_key(key))
    }

    /// Borrows the value for `key`, panicking when absent.
    ///
    /// Mirrors C++ `at()`, which throws `std::out_of_range`.
    pub fn at<Q>(&self, key: &Q) -> &V
    where
        K: Borrow<Q>,
        Q: Hash + Eq + ?Sized,
    {
        self.get(key).expect("hopscotch_map::at: key not found")
    }

    /// Mutably borrows the value for `key`, panicking when absent.
    pub fn at_mut<Q>(&mut self, key: &Q) -> &mut V
    where
        K: Borrow<Q>,
        Q: Hash + Eq + ?Sized,
    {
        self.get_mut(key).expect("hopscotch_map::at: key not found")
    }

    /// Returns the value for `key`, inserting `V::default()` first when absent.
    ///
    /// This is C++ `operator[]` with an owned key.
    #[inline]
    pub fn get_or_insert_default(&mut self, key: K) -> &mut V
    where
        V: Default,
    {
        self.get_or_insert_with(key, V::default)
    }

    /// Returns the value for `key`, inserting `make_value()` first when absent.
    pub fn get_or_insert_with<F>(&mut self, key: K, make_value: F) -> &mut V
    where
        F: FnOnce() -> V,
    {
        let (position, _) = self.table.insert_with(key, make_value);
        self.table.value_at_mut(position)
    }

    /// C++ `operator[]` for a borrowed key: clones the key only when inserting.
    pub fn index_or_insert_default(&mut self, key: &K) -> &mut V
    where
        K: Clone,
        V: Default,
    {
        if let Some(position) = self.table.find(key) {
            return self.table.value_at_mut(position);
        }
        self.get_or_insert_with(key.clone(), V::default)
    }

    /// Removes `key`, returning its value. Mirrors C++ `erase()`.
    #[inline]
    pub fn remove<Q>(&mut self, key: &Q) -> Option<V>
    where
        K: Borrow<Q>,
        Q: Hash + Eq + ?Sized,
    {
        self.table.remove(key)
    }

    /// Removes `key`, returning the stored key and value.
    #[inline]
    pub fn remove_entry<Q>(&mut self, key: &Q) -> Option<(K, V)>
    where
        K: Borrow<Q>,
        Q: Hash + Eq + ?Sized,
    {
        self.table.remove_entry(key)
    }

    /// Retains only the entries for which `keep` returns `true`.
    pub fn retain<F>(&mut self, mut keep: F)
    where
        F: FnMut(&K, &mut V) -> bool,
        K: Clone,
    {
        let doomed: Vec<K> = self
            .iter_mut()
            .filter_map(|(k, v)| if keep(k, v) { None } else { Some(k.clone()) })
            .collect();
        for key in doomed {
            self.remove(&key);
        }
    }

    /// Physical location of `key`, for tests and diagnostics.
    #[inline]
    pub fn position_of<Q>(&self, key: &Q) -> Option<Position>
    where
        K: Borrow<Q>,
        Q: Hash + Eq + ?Sized,
    {
        self.table.find(key)
    }
}

impl<K, V> Default for HopscotchMap<K, V, CppStdHash> {
    fn default() -> Self {
        HopscotchMap::new()
    }
}

/// Order-independent equality, matching C++ `operator==` for unordered maps: equal sizes, and
/// every key of `self` present in `other` with an equal value.
impl<K, V, S> PartialEq for HopscotchMap<K, V, S>
where
    K: Hash + Eq,
    V: PartialEq,
    S: BuildHasher,
{
    fn eq(&self, other: &Self) -> bool {
        if self.len() != other.len() {
            return false;
        }
        self.iter()
            .all(|(key, value)| other.get(key).map_or(false, |other_value| value == other_value))
    }
}

impl<K, V, S> Eq for HopscotchMap<K, V, S>
where
    K: Hash + Eq,
    V: Eq,
    S: BuildHasher,
{
}

impl<K, V, S> fmt::Debug for HopscotchMap<K, V, S>
where
    K: fmt::Debug,
    V: fmt::Debug,
{
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.debug_map().entries(self.iter()).finish()
    }
}

impl<K, Q, V, S> Index<&Q> for HopscotchMap<K, V, S>
where
    K: Hash + Eq + Borrow<Q>,
    Q: Hash + Eq + ?Sized,
    S: BuildHasher,
{
    type Output = V;

    /// Panicking lookup, like C++ `at()` — the immutable form cannot insert.
    fn index(&self, key: &Q) -> &V {
        self.at(key)
    }
}

/// `map[&key] = value`, the direct analogue of C++ `map[key] = value`: a missing key is
/// default-constructed and inserted first.
impl<K, V, S> IndexMut<&K> for HopscotchMap<K, V, S>
where
    K: Hash + Eq + Clone,
    V: Default,
    S: BuildHasher,
{
    fn index_mut(&mut self, key: &K) -> &mut V {
        self.index_or_insert_default(key)
    }
}

impl<K, V, S> IntoIterator for HopscotchMap<K, V, S> {
    type Item = (K, V);
    type IntoIter = IntoIter<K, V>;

    fn into_iter(self) -> IntoIter<K, V> {
        let len = self.table.len();
        let (slots, overflow) = self.table.into_parts();
        IntoIter::new(slots, overflow, len)
    }
}

impl<'a, K, V, S> IntoIterator for &'a HopscotchMap<K, V, S> {
    type Item = (&'a K, &'a V);
    type IntoIter = Iter<'a, K, V>;

    fn into_iter(self) -> Iter<'a, K, V> {
        self.iter()
    }
}

impl<'a, K, V, S> IntoIterator for &'a mut HopscotchMap<K, V, S> {
    type Item = (&'a K, &'a mut V);
    type IntoIter = IterMut<'a, K, V>;

    fn into_iter(self) -> IterMut<'a, K, V> {
        self.iter_mut()
    }
}

/// Later duplicates replace earlier ones, following the `std` collection convention (note that
/// this differs from [`HopscotchMap::insert`], which keeps the existing value like C++ does).
impl<K, V, S> Extend<(K, V)> for HopscotchMap<K, V, S>
where
    K: Hash + Eq,
    S: BuildHasher,
{
    fn extend<T: IntoIterator<Item = (K, V)>>(&mut self, iter: T) {
        let iter = iter.into_iter();
        self.reserve(iter.size_hint().0);
        for (key, value) in iter {
            self.insert_or_assign(key, value);
        }
    }
}

impl<'a, K, V, S> Extend<(&'a K, &'a V)> for HopscotchMap<K, V, S>
where
    K: Hash + Eq + Clone,
    V: Clone,
    S: BuildHasher,
{
    fn extend<T: IntoIterator<Item = (&'a K, &'a V)>>(&mut self, iter: T) {
        for (key, value) in iter {
            self.insert_or_assign(key.clone(), value.clone());
        }
    }
}

impl<K, V, S> FromIterator<(K, V)> for HopscotchMap<K, V, S>
where
    K: Hash + Eq,
    S: BuildHasher + Default,
{
    fn from_iter<T: IntoIterator<Item = (K, V)>>(iter: T) -> Self {
        let mut map = HopscotchMap::with_hasher(S::default());
        map.extend(iter);
        map
    }
}

impl<K, V, const N: usize> From<[(K, V); N]> for HopscotchMap<K, V, CppStdHash>
where
    K: Hash + Eq,
{
    fn from(entries: [(K, V); N]) -> Self {
        entries.into_iter().collect()
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    type Map = HopscotchMap<i32, i32>;

    /// Builds the map the C++ program builds.
    fn built(count: i32) -> Map {
        let mut map = Map::new();
        for i in 0..count {
            map.insert_pair((i, i.wrapping_mul(11)));
        }
        map
    }

    #[test]
    fn reproduces_the_cpp_scenario_for_every_interesting_count() {
        for count in [0, 1, 2, 3, 5, 10, 14, 15, 16, 17, 62, 63, 64, 100, 1000] {
            let map1 = built(count);
            let mut map2 = built(count);
            assert!(map1 == map2, "identically built maps must compare equal (count={})", count);
            map2[&0] = 999;
            assert!(map1 != map2, "mutating map2 must break equality (count={})", count);
            map1.assert_invariants();
            map2.assert_invariants();
        }
    }

    #[test]
    fn negative_count_builds_an_empty_map() {
        let map = built(-5);
        assert!(map.is_empty());
        assert_eq!(map.bucket_count(), 0, "no insert means no allocation");
    }

    #[test]
    fn index_mut_default_inserts_like_cpp_operator_index() {
        // count == 0: map2[0] = 999 must *create* key 0, which is what makes the second
        // comparison print 0 rather than 1.
        let map1 = built(0);
        let mut map2 = built(0);
        assert_eq!(map1.len(), 0);
        assert_eq!(map2.len(), 0);
        assert!(map1 == map2);
        map2[&0] = 999;
        assert_eq!(map2.len(), 1);
        assert_eq!(map2.get(&0), Some(&999));
        assert!(map1 != map2);
    }

    #[test]
    fn index_mut_on_existing_key_overwrites_in_place() {
        let mut map = built(5);
        let before = map.len();
        map[&3] = -7;
        assert_eq!(map.len(), before);
        assert_eq!(map.get(&3), Some(&-7));
    }

    #[test]
    fn insert_keeps_the_existing_value_like_cpp() {
        let mut map = Map::new();
        assert!(map.insert(1, 10));
        assert!(!map.insert(1, 20));
        assert_eq!(map.get(&1), Some(&10));
        assert_eq!(map.insert_or_assign(1, 20), Some(10));
        assert_eq!(map.get(&1), Some(&20));
    }

    #[test]
    fn equality_ignores_iteration_order() {
        let mut ascending = Map::new();
        for i in 0..500 {
            ascending.insert(i, i * 11);
        }
        let mut descending = Map::new();
        for i in (0..500).rev() {
            descending.insert(i, i * 11);
        }
        // Different insertion order can produce a different physical layout ...
        let order_a: Vec<i32> = ascending.keys().copied().collect();
        let order_b: Vec<i32> = descending.keys().copied().collect();
        let _ = (order_a, order_b);
        // ... but equality must not care.
        assert!(ascending == descending);
        assert_eq!(ascending, descending);
    }

    #[test]
    fn equality_detects_value_and_size_differences() {
        let a = built(10);
        let mut b = built(10);
        assert_eq!(a, b);
        b.insert(10, 110);
        assert_ne!(a, b, "different sizes");
        b.remove(&10);
        assert_eq!(a, b);
        *b.get_mut(&4).unwrap() = 0;
        assert_ne!(a, b, "different value for key 4");
        // Same size, disjoint keys.
        let mut c = Map::new();
        for i in 100..110 {
            c.insert(i, i * 11);
        }
        assert_eq!(a.len(), c.len());
        assert_ne!(a, c);
    }

    #[test]
    fn count_and_contains_and_at() {
        let map = built(3);
        assert_eq!(map.count(&0), 1);
        assert_eq!(map.count(&99), 0);
        assert!(map.contains_key(&2));
        assert!(!map.contains_key(&3));
        assert_eq!(*map.at(&2), 22);
        assert_eq!(map[&2], 22);
    }

    #[test]
    #[should_panic(expected = "key not found")]
    fn at_panics_for_missing_key() {
        let map = built(3);
        let _ = map.at(&42);
    }

    #[test]
    fn iteration_visits_every_entry_once() {
        let map = built(1000);
        let mut keys: Vec<i32> = map.iter().map(|(k, _)| *k).collect();
        keys.sort_unstable();
        assert_eq!(keys, (0..1000).collect::<Vec<i32>>());
        assert_eq!(map.iter().len(), 1000);
        assert_eq!(map.iter().count(), 1000);
        let sum: i64 = map.values().map(|v| *v as i64).sum();
        assert_eq!(sum, (0..1000i64).map(|i| i * 11).sum::<i64>());
    }

    #[test]
    fn iter_mut_and_values_mut_mutate_in_place() {
        let mut map = built(50);
        for (_, v) in map.iter_mut() {
            *v += 1;
        }
        for i in 0..50 {
            assert_eq!(map.get(&i), Some(&(i * 11 + 1)));
        }
        for v in map.values_mut() {
            *v = 0;
        }
        assert!(map.values().all(|v| *v == 0));
    }

    #[test]
    fn into_iter_yields_every_entry() {
        let map = built(200);
        let mut entries: Vec<(i32, i32)> = map.into_iter().collect();
        entries.sort_unstable();
        assert_eq!(entries, (0..200).map(|i| (i, i * 11)).collect::<Vec<_>>());
    }

    #[test]
    fn from_iter_and_extend_replace_duplicates() {
        let map: Map = vec![(1, 1), (2, 2), (1, 111)].into_iter().collect();
        assert_eq!(map.len(), 2);
        assert_eq!(map.get(&1), Some(&111), "Extend follows std: last wins");
        let mut map2 = Map::from([(1, 1), (2, 2)]);
        map2.extend(vec![(3, 3)]);
        assert_eq!(map2.len(), 3);
    }

    #[test]
    fn clone_is_independent_and_equal() {
        let map = built(100);
        let mut clone = map.clone();
        assert_eq!(map, clone);
        clone.insert(1000, 1);
        assert_ne!(map, clone);
        assert_eq!(map.len(), 100);
    }

    #[test]
    fn debug_renders_entries() {
        let mut map = Map::new();
        map.insert(1, 11);
        assert_eq!(format!("{:?}", map), "{1: 11}");
    }

    #[test]
    fn retain_keeps_matching_entries() {
        let mut map = built(20);
        map.retain(|k, _| k % 2 == 0);
        assert_eq!(map.len(), 10);
        assert!(map.keys().all(|k| k % 2 == 0));
        map.assert_invariants();
    }

    #[test]
    fn swap_exchanges_contents() {
        let mut a = built(3);
        let mut b = built(7);
        a.swap(&mut b);
        assert_eq!(a.len(), 7);
        assert_eq!(b.len(), 3);
    }

    #[test]
    fn string_keys_and_borrowed_lookup() {
        let mut map: HopscotchMap<String, usize> = HopscotchMap::new();
        map.insert("one".to_string(), 1);
        map.insert("two".to_string(), 2);
        assert_eq!(map.get("one"), Some(&1));
        assert_eq!(map["two"], 2);
        assert!(map.get("three").is_none());
        assert_eq!(map.remove("one"), Some(1));
        assert_eq!(map.len(), 1);
    }

    #[test]
    fn empty_maps_are_equal() {
        assert_eq!(Map::new(), Map::new());
        assert_eq!(Map::new(), Map::with_capacity(1000));
    }
}

