    #[test]
    fn reproduces_the_cpp_scenario_for_every_interesting_count() {
        for count in [0, 1, 2, 3, 5, 10, 14, 15, 16, 17, 62, 63, 64, 100, 1000] {
            let map1 = built(count);
            let mut map2 = built(count);
            assert!(map1 == map2, "identically built maps must compare equal (count={})", count);
            map2[&0] = 999;
            assert!(map1 != map2, "mutating map2 must break equality (count={})", count);
            map1.assert_invariants();
            map2.assert_invariants();
        }
    }

    #[test]
    fn negative_count_builds_an_empty_map() {
        let map = built(-5);
        assert!(map.is_empty());
        assert_eq!(map.bucket_count(), 0, "no insert means no allocation");
    }

    #[test]
    fn index_mut_default_inserts_like_cpp_operator_index() {
        // count == 0: map2[0] = 999 must *create* key 0, which is what makes the second
        // comparison print 0 rather than 1.
        let map1 = built(0);
        let mut map2 = built(0);
        assert_eq!(map1.len(), 0);
        assert_eq!(map2.len(), 0);
        assert!(map1 == map2);
        map2[&0] = 999;
        assert_eq!(map2.len(), 1);
        assert_eq!(map2.get(&0), Some(&999));
        assert!(map1 != map2);
    }

    #[test]
    fn index_mut_on_existing_key_overwrites_in_place() {
        let mut map = built(5);
        let before = map.len();
        map[&3] = -7;
        assert_eq!(map.len(), before);
        assert_eq!(map.get(&3), Some(&-7));
    }

    #[test]
    fn insert_keeps_the_existing_value_like_cpp() {
        let mut map = Map::new();
        assert!(map.insert(1, 10));
        assert!(!map.insert(1, 20));
        assert_eq!(map.get(&1), Some(&10));
        assert_eq!(map.insert_or_assign(1, 20), Some(10));
        assert_eq!(map.get(&1), Some(&20));
    }

    #[test]
    fn equality_ignores_iteration_order() {
        let mut ascending = Map::new();
        for i in 0..500 {
            ascending.insert(i, i * 11);
        }
        let mut descending = Map::new();
        for i in (0..500).rev() {
            descending.insert(i, i * 11);
        }
        // Different insertion order can produce a different physical layout ...
        let order_a: Vec<i32> = ascending.keys().copied().collect();
        let order_b: Vec<i32> = descending.keys().copied().collect();
        let _ = (order_a, order_b);
        // ... but equality must not care.
        assert!(ascending == descending);
        assert_eq!(ascending, descending);
    }

