//! A faithful Rust reimplementation of `std::stoi`.
//!
//! `std::stoi(const std::string&)` is specified as `strtol(str.c_str(), &end, 10)` followed by
//! range checks, so its accepted grammar is wider than Rust's `str::parse::<i32>()`:
//!
//! ```text
//! stoi := whitespace* [+-]? digit+ anything*
//! ```
//!
//! * leading whitespace (`" \t\n\v\f\r"`) is skipped
//! * an optional `+`/`-` sign is accepted
//! * decimal digits are consumed until the first non-digit; trailing garbage is *ignored*
//!   (`"12abc"` → `12`, `"0x10"` → `0`, `"3.9"` → `3`)
//! * no digits at all → `std::invalid_argument`
//! * a value outside `int` (or outside `long`, which `strtol` reports via `ERANGE`) →
//!   `std::out_of_range`
//!
//! Both exceptions escape `main` in the original program, so they end the process through
//! `std::terminate`; see [`crate::cpp::terminate`].

/// Which `std::stoi` exception the C++ original would have thrown.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum StoiError {
    /// `std::invalid_argument` — no digits could be consumed.
    InvalidArgument,
    /// `std::out_of_range` — the parsed value does not fit in an `int`.
    OutOfRange,
}

impl StoiError {
    /// The C++ exception type name, as printed by `std::terminate`.
    pub fn exception_type(self) -> &'static str {
        match self {
            StoiError::InvalidArgument => "std::invalid_argument",
            StoiError::OutOfRange => "std::out_of_range",
        }
    }

    /// The `what()` string libstdc++ attaches to the exception.
    pub fn what(self) -> &'static str {
        // libstdc++'s __throw_invalid_argument / __throw_out_of_range_fmt for stoi both use the
        // function name as the message.
        "stoi"
    }
}

/// `true` for the bytes `isspace` accepts in the C locale.
#[inline]
fn is_space(byte: u8) -> bool {
    matches!(byte, b' ' | b'\t' | b'\n' | 0x0b | 0x0c | b'\r')
}

/// Parses `text` exactly like `std::stoi`.
///
/// Operates on bytes rather than `&str` because C++ works on the raw `char*` from `argv`.
pub fn stoi(text: &[u8]) -> Result<i32, StoiError> {
    let mut index = 0usize;
    while index < text.len() && is_space(text[index]) {
        index += 1;
    }

    let negative = match text.get(index) {
        Some(b'-') => {
            index += 1;
            true
        }
        Some(b'+') => {
            index += 1;
            false
        }
        _ => false,
    };

    let digits_start = index;
    // Accumulate in i128 so that even a long run of digits cannot wrap; `strtol` reports any
    // overflow past `long` as ERANGE, which stoi turns into out_of_range, so saturating at a
    // magnitude above i64::MAX is indistinguishable from the real thing.
    let mut magnitude: i128 = 0;
    let mut overflowed = false;
    while let Some(&byte) = text.get(index) {
        if !byte.is_ascii_digit() {
            break;
        }
        index += 1;
        if !overflowed {
            magnitude = magnitude * 10 + (byte - b'0') as i128;
            if magnitude > i64::MAX as i128 + 1 {
                overflowed = true;
            }
        }
    }

    if index == digits_start {
        return Err(StoiError::InvalidArgument);
    }
    if overflowed {
        return Err(StoiError::OutOfRange);
    }

    let value = if negative { -magnitude } else { magnitude };
    if value < i32::MIN as i128 || value > i32::MAX as i128 {
        return Err(StoiError::OutOfRange);
    }
    Ok(value as i32)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn plain_decimal() {
        assert_eq!(stoi(b"0"), Ok(0));
        assert_eq!(stoi(b"1"), Ok(1));
        assert_eq!(stoi(b"14"), Ok(14));
        assert_eq!(stoi(b"000014"), Ok(14));
        assert_eq!(stoi(b"2147483647"), Ok(i32::MAX));
        assert_eq!(stoi(b"-2147483648"), Ok(i32::MIN));
    }

    #[test]
    fn signs_and_whitespace() {
        assert_eq!(stoi(b"+7"), Ok(7));
        assert_eq!(stoi(b"-5"), Ok(-5));
        assert_eq!(stoi(b"   12"), Ok(12));
        assert_eq!(stoi(b"\t\n\x0b\x0c\r 9"), Ok(9));
        assert_eq!(stoi(b"  -3"), Ok(-3));
    }

    #[test]
    fn trailing_garbage_is_ignored() {
        assert_eq!(stoi(b"12abc"), Ok(12));
        assert_eq!(stoi(b"0x10"), Ok(0));
        assert_eq!(stoi(b"3.9"), Ok(3));
        assert_eq!(stoi(b"5 6"), Ok(5));
        assert_eq!(stoi(b"7\n"), Ok(7));
    }

    #[test]
    fn invalid_argument_cases() {
        assert_eq!(stoi(b""), Err(StoiError::InvalidArgument));
        assert_eq!(stoi(b"   "), Err(StoiError::InvalidArgument));
        assert_eq!(stoi(b"abc"), Err(StoiError::InvalidArgument));
        assert_eq!(stoi(b"-"), Err(StoiError::InvalidArgument));
        assert_eq!(stoi(b"+"), Err(StoiError::InvalidArgument));
        assert_eq!(stoi(b"--"), Err(StoiError::InvalidArgument));
        assert_eq!(stoi(b"--a"), Err(StoiError::InvalidArgument));
        assert_eq!(stoi(b".5"), Err(StoiError::InvalidArgument));
        assert_eq!(stoi(b"x1"), Err(StoiError::InvalidArgument));
        // Whitespace *after* a sign is not allowed by strtol.
        assert_eq!(stoi(b"- 5"), Err(StoiError::InvalidArgument));
    }

    #[test]
    fn out_of_range_cases() {
        assert_eq!(stoi(b"2147483648"), Err(StoiError::OutOfRange));
        assert_eq!(stoi(b"-2147483649"), Err(StoiError::OutOfRange));
        assert_eq!(stoi(b"99999999999999999999"), Err(StoiError::OutOfRange));
        assert_eq!(stoi(b"9223372036854775808"), Err(StoiError::OutOfRange));
        let huge = "9".repeat(400);
        assert_eq!(stoi(huge.as_bytes()), Err(StoiError::OutOfRange));
        let huge_negative = format!("-{}", "9".repeat(400));
        assert_eq!(stoi(huge_negative.as_bytes()), Err(StoiError::OutOfRange));
    }

    #[test]
    fn exception_names_match_libstdcxx() {
        assert_eq!(StoiError::InvalidArgument.exception_type(), "std::invalid_argument");
        assert_eq!(StoiError::OutOfRange.exception_type(), "std::out_of_range");
        assert_eq!(StoiError::InvalidArgument.what(), "stoi");
        assert_eq!(StoiError::OutOfRange.what(), "stoi");
    }
}

