//! Access to `argc`/`argv` with C++ semantics.
//!
//! The C++ original reads `argv[1]` and `argv[2]` directly.  Two details matter for fidelity:
//!
//! 1. **Raw bytes.** `std::string(argv[1])` copies bytes; it never validates UTF-8.  Rust's
//!    [`std::env::args`] *panics* on a non-UTF-8 argument, so this module uses its byte-preserving
//!    sibling [`std::env::args_os`] and works on `Vec<u8>`.
//! 2. **`argv[argc]` is NULL.** Running the C++ binary as `./test14 --a` makes it construct a
//!    `std::string` from that NULL pointer, which libstdc++ turns into a `std::logic_error`.
//!    [`require`] reproduces that abort instead of silently defaulting.

use super::terminate;

/// The program arguments as raw byte strings, `argv[0]` included.
///
/// `argv().len()` equals C's `argc`.
pub fn argv() -> Vec<Vec<u8>> {
    std::env::args_os().map(os_string_into_bytes).collect()
}

/// Converts one `OsString` argument to the bytes the C runtime handed us.
#[cfg(unix)]
fn os_string_into_bytes(arg: std::ffi::OsString) -> Vec<u8> {
    use std::os::unix::ffi::OsStringExt;
    arg.into_vec()
}

/// Fallback for non-Unix targets, where `OsString` is not guaranteed to be raw bytes.
#[cfg(not(unix))]
fn os_string_into_bytes(arg: std::ffi::OsString) -> Vec<u8> {
    arg.to_string_lossy().into_owned().into_bytes()
}

/// `argv[index]`, or `None` when `index >= argc`.
pub fn get(argv: &[Vec<u8>], index: usize) -> Option<&[u8]> {
    argv.get(index).map(|arg| arg.as_slice())
}

/// `std::string(argv[index])` — aborts like libstdc++ when the pointer would be NULL.
pub fn require(argv: &[Vec<u8>], index: usize) -> &[u8] {
    match get(argv, index) {
        Some(arg) => arg,
        None => terminate::terminate_null_string(),
    }
}

/// `argc > index && std::string(argv[index]) == expected`.
pub fn equals(argv: &[Vec<u8>], index: usize, expected: &[u8]) -> bool {
    get(argv, index) == Some(expected)
}

#[cfg(test)]
mod tests {
    use super::*;

    fn fake(args: &[&str]) -> Vec<Vec<u8>> {
        args.iter().map(|a| a.as_bytes().to_vec()).collect()
    }

    #[test]
    fn get_is_bounds_checked() {
        let argv = fake(&["./test14", "--a", "5"]);
        assert_eq!(get(&argv, 0), Some(&b"./test14"[..]));
        assert_eq!(get(&argv, 1), Some(&b"--a"[..]));
        assert_eq!(get(&argv, 2), Some(&b"5"[..]));
        assert_eq!(get(&argv, 3), None);
    }

    #[test]
    fn equals_matches_cpp_string_comparison() {
        let argv = fake(&["./test14", "--a", "5"]);
        assert!(equals(&argv, 1, b"--a"));
        assert!(!equals(&argv, 1, b"--b"));
        assert!(!equals(&argv, 1, b"--a "), "byte comparison, no trimming");
        assert!(!equals(&argv, 9, b"--a"), "out of range is never equal");
        let empty = fake(&["./test14"]);
        assert!(!equals(&empty, 1, b"--a"));
    }

    #[test]
    fn require_returns_present_arguments() {
        let argv = fake(&["./test14", "--a", ""]);
        assert_eq!(require(&argv, 2), b"");
    }

    #[test]
    fn real_process_arguments_are_readable() {
        // argv[0] always exists for a normally spawned process.
        let argv = argv();
        assert!(!argv.is_empty());
    }
}

