//! Rust port of `hopscotch-map/tests/test14.cpp` — hopscotch map equality.
//!
//! The C++ original:
//!
//! ```cpp
//! int main(int argc, char* argv[]) {
//!     int count = 14;
//!     if (argc > 1 && std::string(argv[1]) == "--a") { count = std::stoi(argv[2]); }
//!     tsl::hopscotch_map<int, int> map1, map2;
//!     for (int i = 0; i < count; i++) { map1.insert({i, i * 11}); map2.insert({i, i * 11}); }
//!     std::cout << (map1 == map2) << " ";
//!     map2[0] = 999;
//!     std::cout << (map1 == map2) << std::endl;
//!     return 0;
//! }
//! ```
//!
//! Two maps built identically compare equal, so the first value printed is `1`.  Then
//! `map2[0] = 999` either overwrites key `0` (when `count > 0`) or *inserts* it (when the loop
//! never ran), and either way the maps differ, so the second value is `0`.  The output is
//! therefore always the four bytes `"1 0\n"`.
//!
//! Build (from this directory):
//!
//! ```text
//! rustc -O test14.rs            # produces ./test14
//! cargo build --release         # produces ./target/release/test14
//! cargo test                    # unit + integration tests
//! ```

#[path = "src/cpp/mod.rs"]
mod cpp;
#[path = "src/tsl/mod.rs"]
mod tsl;

use std::io::{self, Write};

use crate::tsl::HopscotchMap;

/// Default `count` when no `--a` argument is supplied.
const DEFAULT_COUNT: i32 = 14;

/// Multiplier applied to each key to build its value: `map[i] == i * 11`.
const VALUE_MULTIPLIER: i32 = 11;

/// The key whose value the program overwrites before the second comparison.
const MUTATED_KEY: i32 = 0;

/// The value written to [`MUTATED_KEY`].
const MUTATED_VALUE: i32 = 999;

fn main() {
    let argv = cpp::argv::argv();
    let count = parse_count(&argv);

    let mut map1: HopscotchMap<i32, i32> = HopscotchMap::new();
    let mut map2: HopscotchMap<i32, i32> = HopscotchMap::new();

    let mut i = 0i32;
    while i < count {
        // `insert` mirrors C++ `insert({i, i * 11})`: it never overwrites an existing key.
        // `wrapping_mul` matches the two's-complement wraparound a release C++ build performs
        // for `i * 11` once `i` exceeds `INT_MAX / 11`.
        map1.insert_pair((i, i.wrapping_mul(VALUE_MULTIPLIER)));
        map2.insert_pair((i, i.wrapping_mul(VALUE_MULTIPLIER)));
        i += 1;
    }

    let before = map1 == map2;
    // `map2[&MUTATED_KEY] = ...` is C++ `map2[0] = 999`: it default-inserts the key when absent.
    map2[&MUTATED_KEY] = MUTATED_VALUE;
    let after = map1 == map2;

    // `std::cout << bool` prints `1`/`0`, and `std::endl` writes '\n' then flushes.
    // Errors are ignored, matching C++ streams, which only set badbit (e.g. on a closed pipe).
    let mut stdout = io::stdout();
    let _ = write!(stdout, "{} {}\n", cpp_bool(before), cpp_bool(after));
    let _ = stdout.flush();
}

/// `count` from the command line, mirroring the C++ argument handling exactly.
///
/// `argc > 1 && std::string(argv[1]) == "--a"` selects the override; `std::stoi(argv[2])` then
/// parses it, aborting the process the way an uncaught C++ exception would when `argv[2]` is
/// missing or unparsable.
fn parse_count(argv: &[Vec<u8>]) -> i32 {
    if !cpp::argv::equals(argv, 1, b"--a") {
        return DEFAULT_COUNT;
    }
    // `std::string(argv[2])` when only `--a` was passed reads the NULL `argv[argc]`.
    let text = cpp::argv::require(argv, 2);
    match cpp::stoi::stoi(text) {
        Ok(count) => count,
        Err(error) => cpp::terminate::terminate(error.exception_type(), error.what()),
    }
}

/// Renders a `bool` the way `operator<<` does for an `std::ostream` without `boolalpha`.
fn cpp_bool(value: bool) -> u8 {
    u8::from(value)
}

#[cfg(test)]
mod tests {
    use super::*;

    fn fake_argv(args: &[&str]) -> Vec<Vec<u8>> {
        args.iter().map(|a| a.as_bytes().to_vec()).collect()
    }

    /// Runs the program's logic for a given `count` and returns the bytes it would print.
    fn run(count: i32) -> Vec<u8> {
        let mut map1: HopscotchMap<i32, i32> = HopscotchMap::new();
        let mut map2: HopscotchMap<i32, i32> = HopscotchMap::new();
        let mut i = 0i32;
        while i < count {
            map1.insert_pair((i, i.wrapping_mul(VALUE_MULTIPLIER)));
            map2.insert_pair((i, i.wrapping_mul(VALUE_MULTIPLIER)));
            i += 1;
        }
        let before = map1 == map2;
        map2[&MUTATED_KEY] = MUTATED_VALUE;
        let after = map1 == map2;
        format!("{} {}\n", cpp_bool(before), cpp_bool(after)).into_bytes()
    }

    #[test]
    fn output_is_always_one_space_zero_newline() {
        for count in [-100, -1, 0, 1, 2, 3, 5, 10, 13, 14, 15, 16, 17, 61, 62, 63, 64, 100, 5000] {
            assert_eq!(run(count), b"1 0\n", "count={}", count);
        }
    }

    #[test]
    fn cpp_bool_renders_as_int() {
        assert_eq!(cpp_bool(true), 1);
        assert_eq!(cpp_bool(false), 0);
        assert_eq!(format!("{} {}\n", cpp_bool(true), cpp_bool(false)), "1 0\n");
    }

    #[test]
    fn default_count_applies_without_the_flag() {
        assert_eq!(parse_count(&fake_argv(&["./test14"])), 14);
        assert_eq!(parse_count(&fake_argv(&["./test14", "--b", "5"])), 14);
        assert_eq!(parse_count(&fake_argv(&["./test14", "5"])), 14);
        assert_eq!(parse_count(&fake_argv(&["./test14", "x", "--a", "5"])), 14);
        assert_eq!(parse_count(&fake_argv(&["./test14", ""])), 14);
    }

    #[test]
    fn flag_overrides_count() {
        assert_eq!(parse_count(&fake_argv(&["./test14", "--a", "0"])), 0);
        assert_eq!(parse_count(&fake_argv(&["./test14", "--a", "5"])), 5);
        assert_eq!(parse_count(&fake_argv(&["./test14", "--a", "-5"])), -5);
        assert_eq!(parse_count(&fake_argv(&["./test14", "--a", " 12"])), 12);
        assert_eq!(parse_count(&fake_argv(&["./test14", "--a", "12abc"])), 12);
        assert_eq!(parse_count(&fake_argv(&["./test14", "--a", "0x10"])), 0);
        // Extra arguments after the count are ignored, exactly like the C++ original.
        assert_eq!(parse_count(&fake_argv(&["./test14", "--a", "7", "junk"])), 7);
    }

    #[test]
    fn value_multiplier_matches_the_cpp_expression() {
        let mut map: HopscotchMap<i32, i32> = HopscotchMap::new();
        for i in 0..14 {
            map.insert_pair((i, i.wrapping_mul(VALUE_MULTIPLIER)));
        }
        for i in 0..14 {
            assert_eq!(map.get(&i), Some(&(i * 11)));
        }
        assert_eq!(map.len(), 14);
    }
}

